SELECT * FROM match_event
WHERE type = #{type}
AND  deleted = 0

 SELECT * FROM match_event
 WHERE id = #{id}
AND  deleted = 0

SELECT check_in_status FROM event_registration
WHERE event_id = #{eventId}
AND  user_id = #{userId}
AND deleted = 0

SELECT  b.status FROM event_registration a
INNER JOIN  match_event b  ON a.event_id = b.id
WHERE a.user_id = #{userId}
  AND a.event_id = #{eventId}
  AND a.deleted = 0
  AND b.deleted = 0

mapper.update:
UPDATE event_registration
SET check_in_status = 'CHECKED_IN'
WHERE event_id = #{eventId}
AND user_id = #{userId}
AND check_in_status = 'NOT_CHECKED_IN'
AND deleted = 0
